"use client";

import React, { useState } from 'react';
import { useStorage } from '../hooks/useStorage';
import OTPModal from './OTPModal';

const QUICK_PROVIDERS = [
  { id: 'food-a', name: 'Swiggy', icon: '🍔', color: '#fc8019' },
  { id: 'food-b', name: 'Zomato', icon: '🍕', color: '#e23744' },
  { id: 'grocery-a', name: 'Blinkit', icon: '🛒', color: '#f8cb46' },
  { id: 'retail-a', name: 'Amazon', icon: '📦', color: '#232f3e' }
];

export default function QuickConnect() {
  const { connections, actions, isHydrated } = useStorage();
  const [modalOpen, setModalOpen] = useState(false);
  const [selectedProvider, setSelectedProvider] = useState<{id: string, name: string} | null>(null);

  if (!isHydrated) return null;

  const handleConnectClick = (providerId: string, providerName: string) => {
    const isConnected = connections.some(c => c.providerId === providerId && c.status === 'connected');
    
    if (isConnected) {
      actions.disconnectProvider(providerId);
    } else {
      setSelectedProvider({ id: providerId, name: providerName });
      setModalOpen(true);
    }
  };

  const handleOtpSuccess = () => {
    if (selectedProvider) {
      actions.connectProvider(selectedProvider.id);
      setModalOpen(false);
    }
  };

  return (
    <div style={{
      background: 'var(--card-bg)',
      border: '1px solid var(--border)',
      borderRadius: '12px',
      padding: '1.5rem',
      marginBottom: '2rem'
    }}>
      <h3 style={{marginTop: 0, marginBottom: '1rem', fontSize: '1.1rem'}}>Link your accounts for better deals</h3>
      
      <div style={{display: 'flex', gap: '1rem', flexWrap: 'wrap'}}>
        {QUICK_PROVIDERS.map(provider => {
          const isConnected = connections.some(c => c.providerId === provider.id && c.status === 'connected');
          
          return (
            <button
              key={provider.id}
              onClick={() => handleConnectClick(provider.id, provider.name)}
              style={{
                display: 'flex',
                alignItems: 'center',
                gap: '0.75rem',
                padding: '0.75rem 1rem',
                border: `1px solid ${isConnected ? provider.color : 'var(--border)'}`,
                borderRadius: '8px',
                background: isConnected ? `${provider.color}15` : 'transparent',
                cursor: 'pointer',
                transition: 'all 0.2s',
                minWidth: '140px'
              }}
            >
              <div style={{
                width: '32px', height: '32px', 
                borderRadius: '50%', background: provider.color, 
                display: 'flex', alignItems: 'center', justifyContent: 'center',
                color: 'white', fontSize: '1rem'
              }}>
                {provider.icon}
              </div>
              <div style={{textAlign: 'left'}}>
                <div style={{fontWeight: 'bold', fontSize: '0.9rem'}}>{provider.name}</div>
                <div style={{fontSize: '0.75rem', color: isConnected ? provider.color : 'var(--muted)'}}>
                  {isConnected ? 'Connected ✓' : 'Connect'}
                </div>
              </div>
            </button>
          );
        })}
      </div>

      {selectedProvider && (
        <OTPModal 
          providerName={selectedProvider.name}
          isOpen={modalOpen}
          onClose={() => setModalOpen(false)}
          onSuccess={handleOtpSuccess}
        />
      )}
    </div>
  );
}
