"use client";

import React, { useState, useEffect, useRef } from 'react';
import { auth } from '@/lib/firebase';
import {
  RecaptchaVerifier,
  signInWithPhoneNumber,
  ConfirmationResult
} from 'firebase/auth';

interface OTPModalProps {
  providerName: string;
  isOpen: boolean;
  onClose: () => void;
  onSuccess: () => void;
}

export default function OTPModal({ providerName, isOpen, onClose, onSuccess }: OTPModalProps) {
  const [step, setStep] = useState<1 | 2>(1);
  const [phone, setPhone] = useState('');
  const [otp, setOtp] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState('');
  const [confirmationResult, setConfirmationResult] = useState<ConfirmationResult | null>(null);
  const recaptchaVerifierRef = useRef<RecaptchaVerifier | null>(null);

  // Setup invisible reCAPTCHA when modal opens
  useEffect(() => {
    if (!isOpen) return;

    // Clean up any previous instance
    if (recaptchaVerifierRef.current) {
      recaptchaVerifierRef.current.clear();
      recaptchaVerifierRef.current = null;
    }

    const timer = setTimeout(() => {
      try {
        recaptchaVerifierRef.current = new RecaptchaVerifier(auth, 'recaptcha-container', {
          size: 'invisible',
          callback: () => {},
        });
      } catch (e) {
        console.error('reCAPTCHA init error:', e);
      }
    }, 300);

    return () => {
      clearTimeout(timer);
      if (recaptchaVerifierRef.current) {
        recaptchaVerifierRef.current.clear();
        recaptchaVerifierRef.current = null;
      }
    };
  }, [isOpen]);

  const resetModal = () => {
    setStep(1);
    setPhone('');
    setOtp('');
    setError('');
    setConfirmationResult(null);
  };

  const handleClose = () => {
    resetModal();
    onClose();
  };

  const handleSendOtp = async (e: React.FormEvent) => {
    e.preventDefault();
    if (phone.length !== 10) {
      setError('Please enter a valid 10-digit phone number.');
      return;
    }
    setError('');
    setIsLoading(true);

    try {
      if (!recaptchaVerifierRef.current) {
        throw new Error('reCAPTCHA not initialized. Please refresh and try again.');
      }
      const fullPhone = `+91${phone}`;
      const result = await signInWithPhoneNumber(auth, fullPhone, recaptchaVerifierRef.current);
      setConfirmationResult(result);
      setStep(2);
    } catch (err: any) {
      console.error('OTP send error:', err);
      const msg = err?.code === 'auth/too-many-requests'
        ? 'Too many attempts. Please wait a few minutes and try again.'
        : err?.code === 'auth/invalid-phone-number'
        ? 'Invalid phone number. Please check and try again.'
        : err?.code === 'auth/captcha-check-failed'
        ? 'Security check failed. Please refresh the page and try again.'
        : 'Failed to send OTP. Please try again.';
      setError(msg);
    } finally {
      setIsLoading(false);
    }
  };

  const handleVerifyOtp = async (e: React.FormEvent) => {
    e.preventDefault();
    if (otp.length < 6) {
      setError('Please enter the 6-digit OTP.');
      return;
    }
    if (!confirmationResult) {
      setError('Session expired. Please request OTP again.');
      setStep(1);
      return;
    }
    setError('');
    setIsLoading(true);

    try {
      await confirmationResult.confirm(otp);
      onSuccess();
      resetModal();
      onClose();
    } catch (err: any) {
      console.error('OTP verify error:', err);
      const msg = err?.code === 'auth/invalid-verification-code'
        ? 'Incorrect OTP. Please check the code and try again.'
        : err?.code === 'auth/code-expired'
        ? 'OTP has expired. Please request a new one.'
        : 'Verification failed. Please try again.';
      setError(msg);
    } finally {
      setIsLoading(false);
    }
  };

  if (!isOpen) return null;

  const inputStyle: React.CSSProperties = {
    flex: 1, padding: '0.75rem',
    border: '1px solid var(--border)', borderRadius: '0 6px 6px 0',
    fontSize: '1rem', background: 'var(--background)', color: 'var(--foreground)',
    width: '100%', outline: 'none',
  };

  const btnStyle: React.CSSProperties = {
    width: '100%', padding: '0.75rem',
    background: 'var(--primary)', color: 'white',
    border: 'none', borderRadius: '6px',
    fontSize: '1rem', fontWeight: 'bold',
    cursor: isLoading ? 'not-allowed' : 'pointer',
    opacity: isLoading ? 0.7 : 1,
    transition: 'opacity 0.2s',
  };

  return (
    <div style={{
      position: 'fixed', top: 0, left: 0, right: 0, bottom: 0,
      backgroundColor: 'rgba(0, 0, 0, 0.7)',
      display: 'flex', justifyContent: 'center', alignItems: 'center',
      zIndex: 1000, padding: '1rem'
    }}>
      {/* Invisible reCAPTCHA container — Firebase requires this DOM element */}
      <div id="recaptcha-container" />

      <div style={{
        background: 'var(--card-bg)', width: '100%', maxWidth: '400px',
        borderRadius: '12px', padding: '2rem',
        boxShadow: '0 20px 25px -5px rgba(0,0,0,0.1), 0 10px 10px -5px rgba(0,0,0,0.04)',
        position: 'relative', color: 'var(--foreground)'
      }}>
        <button onClick={handleClose} style={{
          position: 'absolute', top: '1rem', right: '1rem',
          background: 'none', border: 'none', fontSize: '1.5rem',
          cursor: 'pointer', color: 'var(--muted)'
        }}>
          &times;
        </button>

        <h2 style={{ marginTop: 0, marginBottom: '0.5rem' }}>Connect {providerName}</h2>
        <p style={{ color: 'var(--muted)', fontSize: '0.875rem', marginBottom: '1.5rem' }}>
          We use your number to fetch {providerName} specific discounts.{' '}
          <strong>Your credentials will only be saved locally on this device.</strong>
        </p>

        {error && (
          <div style={{
            background: '#fee2e2', border: '1px solid #fca5a5', borderRadius: '6px',
            padding: '0.75rem', marginBottom: '1rem',
            color: '#b91c1c', fontSize: '0.875rem'
          }}>
            {error}
          </div>
        )}

        {step === 1 ? (
          <form onSubmit={handleSendOtp}>
            <div style={{ marginBottom: '1.5rem' }}>
              <label style={{ display: 'block', fontSize: '0.875rem', fontWeight: 'bold', marginBottom: '0.5rem' }}>
                Phone Number
              </label>
              <div style={{ display: 'flex' }}>
                <span style={{
                  padding: '0.75rem', background: 'var(--background)',
                  border: '1px solid var(--border)', borderRight: 'none',
                  borderRadius: '6px 0 0 6px', color: 'var(--muted)',
                  whiteSpace: 'nowrap'
                }}>
                  +91
                </span>
                <input
                  type="tel"
                  value={phone}
                  onChange={(e) => {
                    setError('');
                    setPhone(e.target.value.replace(/\D/g, '').slice(0, 10));
                  }}
                  placeholder="Enter your registered number"
                  style={inputStyle}
                  autoFocus
                />
              </div>
            </div>
            <button type="submit" disabled={isLoading || phone.length !== 10} style={btnStyle}>
              {isLoading ? 'Sending OTP...' : 'Get OTP'}
            </button>
          </form>
        ) : (
          <form onSubmit={handleVerifyOtp}>
            <div style={{ marginBottom: '1.5rem' }}>
              <label style={{ display: 'block', fontSize: '0.875rem', fontWeight: 'bold', marginBottom: '0.5rem' }}>
                Enter OTP
              </label>
              <input
                type="text"
                value={otp}
                onChange={(e) => {
                  setError('');
                  setOtp(e.target.value.replace(/\D/g, '').slice(0, 6));
                }}
                placeholder="Enter 6-digit OTP"
                style={{
                  ...inputStyle, borderRadius: '6px',
                  textAlign: 'center', letterSpacing: '0.5rem', fontSize: '1.25rem'
                }}
                autoFocus
              />
              <p style={{ fontSize: '0.75rem', color: 'var(--muted)', marginTop: '0.5rem', textAlign: 'center' }}>
                OTP sent to +91 {phone}.{' '}
                <button
                  type="button"
                  onClick={() => { setStep(1); setOtp(''); setError(''); }}
                  style={{ background: 'none', border: 'none', color: 'var(--primary)', textDecoration: 'underline', cursor: 'pointer' }}
                >
                  Change
                </button>
              </p>
            </div>
            <button type="submit" disabled={isLoading || otp.length < 6} style={btnStyle}>
              {isLoading ? 'Verifying...' : 'Verify & Connect'}
            </button>
          </form>
        )}
      </div>
    </div>
  );
}
